/* ============================================
   ANCHOR NAV
   "On this page" list of anchor links with a
   position indicator riding the left rail.
   ============================================ */
.ds-anchor-nav {
  font-family: var(--font-family-primary);
}

.ds-anchor-nav__header {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  margin: 0 0 var(--gap-200);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  color: var(--color-text-primary);
}

.ds-anchor-nav__icon {
  --icon-size: var(--icon-size-500);
  color: var(--color-icon-primary);
}

.ds-anchor-nav__list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-left: var(--border-025) solid var(--color-divider);
}

.ds-anchor-nav__link {
  display: block;
  padding: var(--padding-150) 0 var(--padding-150) var(--padding-400);
  /* Sits over the list rail; turns into the indicator when active */
  margin-left: calc(var(--border-025) * -1);
  border-left: var(--border-050) solid transparent;
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  color: var(--color-text-tertiary);
  text-decoration: none;
  transition:
    color var(--motion-duration-fast) var(--motion-ease-standard),
    border-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-anchor-nav__link:hover {
  color: var(--color-text-primary);
}

.ds-anchor-nav__link:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
  border-radius: var(--radius-050);
}

.ds-anchor-nav__link--active {
  color: var(--color-text-primary);
  font-weight: var(--font-paragraph-emphasis-weight);
  border-left-color: var(--color-text-primary);
}

/* ============================================
   FLOATING VARIANT
   Collapsed to a minimap of short lines; the
   full panel expands over it on hover, focus
   or tap. The caller positions the nav itself
   (typically fixed on the right page edge).
   ============================================ */
.ds-anchor-nav--floating {
  position: relative;
  display: inline-block;
}

.ds-anchor-nav__lines {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: var(--gap-200);
  /* A comfortable hover/tap target around the thin lines */
  padding: var(--padding-200);
  cursor: pointer;
}

.ds-anchor-nav__line {
  /* One line per section: bespoke minimap geometry, specced in design.md */
  width: 16px;
  height: var(--border-050);
  border-radius: var(--radius-pill);
  background-color: var(--color-divider);
  transition:
    width var(--motion-duration-fast) var(--motion-ease-standard),
    background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-anchor-nav__line--active {
  width: 24px;
  background-color: var(--color-text-primary);
}

.ds-anchor-nav__panel {
  position: absolute;
  z-index: 10;
  top: 50%;
  right: 0;
  min-width: 200px;
  max-width: 280px;
  /* A long list scrolls inside the panel rather than past the viewport */
  max-height: 70vh;
  overflow-y: auto;
  padding: var(--padding-400);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-200);
  /* Page background, not container: the container fill is semi-transparent
     in dark mode, and a floating panel must not show text through itself */
  background-color: var(--color-bg-page-primary);
  box-shadow: var(--shadow-floating);

  /* Hidden by default — but never visibility: hidden, because the links must
     stay focusable so tabbing into the nav expands it via :focus-within */
  opacity: 0;
  pointer-events: none;
  transform: translate(var(--gap-050), -50%);
  transition:
    opacity var(--motion-duration-fast) var(--motion-ease-standard),
    transform var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-anchor-nav--floating:hover .ds-anchor-nav__panel,
.ds-anchor-nav--floating:focus-within .ds-anchor-nav__panel,
.ds-anchor-nav--open .ds-anchor-nav__panel {
  opacity: 1;
  pointer-events: auto;
  transform: translate(0, -50%);
}

'use client';

import React, { useCallback, useEffect, useImperativeHandle, useRef, useState } from 'react';
import './AnchorNav.css';

export interface AnchorNavItem {
  /** The id of the element the item jumps to (rendered as `href="#id"`) */
  id: string;
  /** Link text */
  label: string;
}

type AnchorNavOwnProps = {
  /** The on-page sections to list, in document order */
  items: AnchorNavItem[];
  /** Visual form: `list` renders the inline "On this page" rail; `floating` collapses to a stack of short lines that expands into a panel on hover, keyboard focus, or tap, so it can ride a page edge without taking column width */
  variant?: 'list' | 'floating';
  /** Header text above the list; pass an empty string to render no header */
  title?: string;
  /** Icon beside the header — Material Symbol name (string) or custom element (ReactNode); pass an empty string for none */
  icon?: string | React.ReactNode;
  /** Controlled active item id — set it to drive the highlight yourself and skip scroll tracking */
  activeId?: string;
  /** Fires when the tracked (or clicked) active item changes */
  onActiveChange?: (id: string) => void;
  /** Distance in px from the viewport top at which a section counts as current, e.g. a sticky header's height */
  offset?: number;
};

export interface AnchorNavProps
  extends AnchorNavOwnProps,
    Omit<React.ComponentPropsWithoutRef<'nav'>, keyof AnchorNavOwnProps> {}

/**
 * An "On this page" list of anchor links that tracks the reader's position.
 *
 * Uncontrolled by default: a scroll listener marks the last section whose top
 * has passed `offset` as current. Pass `activeId` to control the highlight
 * instead (no listener is attached). The active link carries
 * `aria-current="location"`.
 *
 * The `floating` variant collapses the list to a minimap of short lines and
 * expands the full panel on hover or keyboard focus (the links stay focusable
 * while collapsed, so tabbing in opens it). A tap opens it where hover
 * doesn't exist; Escape or a click elsewhere closes it again.
 */
export const AnchorNav = React.forwardRef<HTMLElement, AnchorNavProps>(
  (
    {
      items,
      variant = 'list',
      title = 'On this page',
      icon = 'toc',
      activeId,
      onActiveChange,
      offset = 96,
      className,
      onKeyDown,
      ...rest
    },
    ref
  ) => {
    const navRef = useRef<HTMLElement>(null);
    useImperativeHandle(ref, () => navRef.current as HTMLElement);

    const floating = variant === 'floating';
    const [open, setOpen] = useState(false);

    const isControlled = activeId !== undefined;
    const [trackedId, setTrackedId] = useState<string | undefined>(undefined);
    const currentId = isControlled ? activeId : trackedId;

    const onActiveChangeRef = useRef(onActiveChange);
    onActiveChangeRef.current = onActiveChange;

    const setActive = useCallback(
      (id: string | undefined) => {
        setTrackedId((prev) => {
          if (id !== undefined && id !== prev) onActiveChangeRef.current?.(id);
          return id;
        });
      },
      []
    );

    // Scroll tracking: the current section is the last one whose top sits at
    // or above `offset`; before the first section, the first item is current.
    useEffect(() => {
      if (isControlled || items.length === 0) return;
      let frame = 0;
      const measure = () => {
        frame = 0;
        let current = items[0]?.id;
        for (const item of items) {
          const el = document.getElementById(item.id);
          if (!el) continue;
          if (el.getBoundingClientRect().top <= offset + 1) current = item.id;
        }
        setActive(current);
      };
      const schedule = () => {
        if (frame === 0) frame = window.requestAnimationFrame(measure);
      };
      measure();
      window.addEventListener('scroll', schedule, { passive: true });
      window.addEventListener('resize', schedule);
      return () => {
        window.removeEventListener('scroll', schedule);
        window.removeEventListener('resize', schedule);
        if (frame !== 0) window.cancelAnimationFrame(frame);
      };
    }, [isControlled, items, offset, setActive]);

    // Tap-to-open only exists on the floating variant; a click elsewhere or
    // Escape closes it again.
    useEffect(() => {
      if (!open) return;
      const onPointerDown = (event: PointerEvent) => {
        if (navRef.current && !navRef.current.contains(event.target as Node)) setOpen(false);
      };
      document.addEventListener('pointerdown', onPointerDown);
      return () => document.removeEventListener('pointerdown', onPointerDown);
    }, [open]);

    const handleKeyDown = (event: React.KeyboardEvent<HTMLElement>) => {
      onKeyDown?.(event);
      if (floating && event.key === 'Escape') {
        setOpen(false);
        // Collapse the :focus-within expansion too
        const focused = document.activeElement;
        if (focused instanceof HTMLElement && navRef.current?.contains(focused)) focused.blur();
      }
    };

    const classes = [
      'ds-anchor-nav',
      floating && 'ds-anchor-nav--floating',
      floating && open && 'ds-anchor-nav--open',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const header = title ? (
      <p className="ds-anchor-nav__header">
        {icon &&
          (typeof icon === 'string' ? (
            <span className="material-symbols-rounded ds-anchor-nav__icon" aria-hidden="true">
              {icon}
            </span>
          ) : (
            <span className="ds-anchor-nav__icon" aria-hidden="true">
              {icon}
            </span>
          ))}
        {title}
      </p>
    ) : null;

    const list = (
      <ul className="ds-anchor-nav__list">
        {items.map((item) => (
          <li key={item.id}>
            <a
              href={`#${item.id}`}
              className={
                item.id === currentId
                  ? 'ds-anchor-nav__link ds-anchor-nav__link--active'
                  : 'ds-anchor-nav__link'
              }
              aria-current={item.id === currentId ? 'location' : undefined}
              onClick={(event) => {
                if (!isControlled) setActive(item.id);
                else onActiveChangeRef.current?.(item.id);
                if (floating) {
                  setOpen(false);
                  // Release :focus-within so the panel folds away after the jump
                  event.currentTarget.blur();
                }
              }}
            >
              {item.label}
            </a>
          </li>
        ))}
      </ul>
    );

    return (
      <nav
        ref={navRef}
        aria-label={title || 'On this page'}
        className={classes}
        {...rest}
        onKeyDown={handleKeyDown}
      >
        {floating ? (
          <>
            <div className="ds-anchor-nav__lines" aria-hidden="true" onClick={() => setOpen(true)}>
              {items.map((item) => (
                <span
                  key={item.id}
                  className={
                    item.id === currentId
                      ? 'ds-anchor-nav__line ds-anchor-nav__line--active'
                      : 'ds-anchor-nav__line'
                  }
                />
              ))}
            </div>
            <div className="ds-anchor-nav__panel">
              {header}
              {list}
            </div>
          </>
        ) : (
          <>
            {header}
            {list}
          </>
        )}
      </nav>
    );
  }
);

AnchorNav.displayName = 'AnchorNav';
